update public.poetry as p
set body = x.body
from (
  select x->>'slug' as slug, x->>'body' as body
  from jsonb_array_elements($bodies$[{"slug":"tum-p096","body":"میں شاعر ہوں  لڑکی ، مجھے\nلفظوں سے کھیلنے کی عادت ہے\nآنکھیں جھاکنا، چہرے جانچنا\nدکھ تراشنا ، الم آشنا\nیہی میرا مشغلہ ہے\nاک عمر سے یہی سلسلہ ہے\nاور تم ؟ تم متاع جاں\nاک ابھرتی سی سحر ہو\nفقط غم کی لہر ہو\nجس پہ مجھے اکثر\nاپنے لفظوں کی ناؤ\nتھرتھراتی نظر آتی ہے\nجو پانی کے بہاؤ سے\nسمت بدلتی جاتی ہے\nیہ ناؤ جسے ساحل پہ اترتے ہی\nکسی اور منزل کی تلاش ہوگی\nسفر کی  کوئی خبر نہ ہوگی\nتم سی کوئی لہر اثر نہ ہوگی"},{"slug":"tum-p097","body":"وہ چھت پہ جب ٹہلا ہوگا\nچاند نے بھی اسے دیکھا ہوگا\n\nستاروں کی بھیڑ میں بھی\nوہ شخص اکیلا چمکا ہوگا\n\nبند لبوں کے سسکنے سے\nکچھ نہ کچھ تو سنا ہوگا\n\nرات کے پچھلے پہر میں\nکوئی سویا کوئی جاگا ہوگا\n\nدور ساحل کے اس پار\nآخر کوئی تو پہنچا ہوگا\n\nپیٹھ جب پھیری ہوگی\nمڑ کے تو دیکھا ہوگا\n\nکئی یادیں جلی ہونگی\nپھر سگریٹ جلا ہوگا\n\nخدا سے ملنے کا احمد ؔ\nاور بھی کوئی رستہ ہوگا"},{"slug":"tum-p098","body":"تجھے اب کسی غم سے آشنا نہ کریں گے\nبچھڑ جائیں گے لیکن اظہارِ تمنا نہ کریں گے\n\nشبِ ہجر شاید یونہی گزر جائے گی\nلبِ بام ستارے بھی چمکا نہ کریں گے\n\nآ کہ اب چلیں گے زمانے کے دستوروں پہ\nمحبت کریں گے دونوں پر بھروسہ نہ کریں گے\n\nاک ماہ یوں بھی گزرا ہے دل پہ صیام کا\nتیرے سامنے سے گزرے ہم کہ سامنا نہ کریں گے\n\nکالج کے دوستوں کی بات بھی سچی تھی\nیہاں سے نکل کے پھر ہم یوں ملا نہ کریں گے\n\nسنا تھا کہ محبت میں خسارے ہیں بہت\nسوچا تھا کہ اپنا خسارہ نہ کریں گے\n\nاب اندھیرے میں کریں گے روشنی کا انتظار\nاب ہم مفت کے دیپ جلایا نہ کریں گے\n\nتیرے بعد ہر رات کی کہانی یہی رہی\nاحمد ؔ کل سے صبح تک جاگا نہ کریں گے"},{"slug":"tum-p099","body":"کیوں ناں اے دوست اک کام کریں\nعمرِ دَوّام کریں، گفتگو عام کریں\n\nبیٹھ کے مسرت و الم کے ساحل پہ\nانتظارِ شام کریں، سحر تمام کریں\n\nزندگی، کس خواب کے تعقب میں گزرے\nکسے غلام کریں ، کسے امام کریں\n\nدل تو کرتا ہے کہ تجھے سامنے پا کر\nتجھ سے دور رہیں، تجھ سے صیام کریں\n\nناصح ہم جو چپ ہیں تو یہی اچھا ہے\nرخ بدلیں گے ، ہم اگر کلام کریں\n\nہم لکھتے ہیں بےقصدِ نتائج ، کہ یہ الفاظ\nاحمد ؔ چاہے تو نام کریں، چاہے بدنام کریں"},{"slug":"tum-p100","body":"درد دل کے بڑھتے رہے\nہم ہاتھ ملتے رہے\n\nہمسفر بدلتے رہے\nہم سفر کو چلتے رہے\n\nرات ڈھل گئی تھی\nدیے مگر جلتے رہے\n\nبہار بھی چمن پہ آتی رہی\nپھول بھی ٹوٹ کے گرتے رہے\n\nدل شکن تھے دونوں ہی\nوہ بس سنورتے رہے\n\nخواب اتنے دیکھ لیے کہ\nحقیقت میں سوتے رہے\n\nلوگ بہت ملے تم سے بہتر بھی احمد\nبس ہم تیری جھلک کو ترستے رہے"}]$bodies$::jsonb) x
) as x
where p.slug = x.slug;
